import type { Q } from "../types";

export const ibPart2: Q[] = [
  { t: "Accretion and dilution in plain terms", p: "What does it mean for a deal to be accretive or dilutive, and which numbers do you compare to find out?", d: 1, tp: "ib-ma", i: "A deal is accretive if the acquirer's pro forma earnings per share are higher than its standalone EPS, and dilutive if lower. You compare standalone EPS with pro forma EPS, where pro forma net income combines both companies' earnings, adds synergies, subtracts new after-tax interest and lost interest on cash, and subtracts any extra amortization from asset write-ups, then divides by the acquirer's old shares plus any newly issued shares. It is an accounting measure, not proof that value is created.", c: ["Compare pro forma EPS with standalone EPS", "Combined net income adjusted for synergies, financing costs and write-up amortization", "Share count rises with newly issued stock", "EPS accretion is not the same as value creation"], k: ["Both the numerator and the denominator move in a deal", "A deal can be accretive yet destroy value if the price is too high"], m: ["Treating accretive as automatically good for shareholders"] },
  { t: "Quick P/E test for an all-stock deal", p: "In an all-stock acquisition with no synergies, how can you tell from the two companies' P/E ratios whether the deal is accretive?", d: 1, tp: "ib-ma", tp2: "ib-valuation", i: "In an all-stock deal the acquirer is effectively paying with its own earnings yield. If the acquirer's P/E is higher than the P/E being paid for the target (offer price over target EPS), the acquirer is issuing relatively expensive shares to buy relatively cheap earnings, so EPS rises and the deal is accretive. If the acquirer's P/E is lower than the P/E paid, the deal is dilutive. Synergies, write-up amortization and transaction costs shift the answer at the margin.", c: ["Compare acquirer P/E with the P/E paid for the target", "Higher acquirer P/E means accretive in an all-stock deal", "Uses the offer price, so the premium matters", "Synergies and amortization can change the result"], k: ["Cost of stock is roughly the inverse of the acquirer's P/E", "A higher premium raises the P/E paid and reduces accretion"], m: ["Using the target's unaffected P/E and ignoring the premium"] },
  { t: "Cost of financing a deal with cash, debt or stock", p: "How do you compare the true cost of paying with cash, new debt and newly issued stock when assessing accretion?", d: 2, tp: "ib-ma", i: "Cash costs the interest income given up, after tax: pre-tax yield on cash times one minus the tax rate. New debt costs the interest rate times one minus the tax rate, because interest is deductible. Stock costs roughly the acquirer's earnings yield, the inverse of its P/E, and has no tax shield. A deal is more accretive with the cheapest source, so a high-P/E acquirer favors stock while a low-P/E acquirer with cheap debt favors debt. Debt capacity, ratings and risk limit how far this logic can be pushed.", c: ["Cash cost is forgone after-tax interest income", "Debt cost is interest times one minus tax rate", "Stock cost is approximately the inverse of the P/E", "Cheapest source is most accretive but risk and capacity constrain it"], k: ["Debt is usually the cheapest accounting source but raises leverage and risk", "Compare earnings yield with after-tax cost of debt"], m: ["Assuming stock is free because no cash leaves the company"] },
  { t: "Breakeven synergies", p: "What are breakeven synergies in a merger model, and how would you calculate them for a dilutive deal?", d: 3, tp: "ib-ma", i: "Breakeven synergies are the pre-tax synergies needed so that pro forma EPS equals the acquirer's standalone EPS. Compute the pro forma net income needed to reach standalone EPS: standalone EPS times pro forma shares. Subtract the pro forma net income before synergies to get the after-tax shortfall, then divide by one minus the tax rate to gross it up to pre-tax synergies. It tells the board how achievable the synergy target must be relative to the cost base being combined.", c: ["Synergies needed for pro forma EPS to equal standalone EPS", "Required net income is standalone EPS times pro forma shares", "Shortfall grossed up by one minus the tax rate", "Judge the figure as a share of the combined cost base or target costs"], k: ["A small breakeven figure makes accretion robust", "Pre-tax versus after-tax confusion is the common error"], m: ["Forgetting to divide the after-tax shortfall by one minus tax rate"] },
  { t: "Control premium and how it is set", p: "What is a control premium, and how would you judge whether a proposed offer premium is reasonable?", d: 1, tp: "ib-ma", tp2: "ib-valuation", i: "A control premium is the amount above the target's unaffected share price that an acquirer pays to gain control and the ability to direct strategy and capture synergies. You judge it against premiums in comparable precedent transactions, the target's trading range and 52-week high, the value of expected synergies, a standalone DCF and what competing bidders might pay. The acquirer should not hand over all the synergy value, while the target board wants a price that clears shareholder approval.", c: ["Premium over the unaffected share price", "Benchmark against precedent transaction premiums", "Reference trading history and standalone valuation", "Premium should be below the value of synergies"], k: ["Unaffected price is measured before rumors or announcement", "Premiums vary by sector and market conditions"], m: ["Measuring the premium from a price already inflated by leaks"] },
  { t: "Purchase price allocation and goodwill", p: "Explain how goodwill is created in an acquisition and what happens to it on the combined balance sheet.", d: 2, tp: "ib-ma", tp2: "ib-accounting", i: "Under acquisition accounting the purchase price is allocated to the target's identifiable assets and liabilities at fair value, including intangibles like customer relationships and brands. Goodwill is the excess of purchase price over the fair value of net identifiable assets. The target's old goodwill is eliminated, assets are written up with a related deferred tax liability, and new goodwill is recorded. Under US GAAP and IFRS goodwill is not amortized but tested for impairment, while finite-lived intangibles are amortized and hit earnings.", c: ["Goodwill equals price minus fair value of net identifiable assets", "Assets written up to fair value, intangibles identified", "Existing target goodwill is eliminated", "Goodwill is tested for impairment, not amortized"], k: ["Write-ups of finite-lived assets create extra expense in the merger model", "Impairment is non-cash but signals overpayment"], m: ["Thinking goodwill is amortized against EPS each year"] },
  { t: "Deferred tax liability from asset write-ups", p: "When a stock acquisition writes up asset values, why does a deferred tax liability appear and how does it affect goodwill?", d: 3, tp: "ib-ma", tp2: "ib-accounting", i: "In a stock purchase the tax basis of the target's assets carries over, so a book write-up creates higher future book depreciation or amortization than tax deductions. That temporary difference is recorded as a deferred tax liability equal to the write-up times the tax rate. The DTL reduces net identifiable assets, so goodwill increases by the same amount. Over time the DTL unwinds as the extra book expense is recognized, with cash taxes unaffected. In an asset sale or a 338(h)(10) election the tax basis steps up, so no DTL arises.", c: ["Book write-up with unchanged tax basis creates a temporary difference", "DTL equals write-up times tax rate", "DTL increases goodwill", "No DTL when tax basis is also stepped up"], k: ["The DTL unwinds as extra book expense is recorded", "Cash taxes do not change from the write-up in a stock deal"], m: ["Believing the write-up gives extra cash tax savings in a stock deal"] },
  { t: "Stock sale versus asset sale", p: "What are the key differences between buying a company's stock and buying its assets, from the buyer and seller perspectives?", d: 3, tp: "ib-ma", tp2: "ib-accounting", i: "In a stock sale the buyer acquires the legal entity with all assets and liabilities, known and unknown, and tax basis carries over, so there is no step-up. Sellers generally prefer this because gains are taxed once at shareholder level. In an asset sale the buyer picks assets and liabilities, gets a tax basis step-up that creates depreciation and amortization deductions, and avoids unknown liabilities, but the seller may face double taxation in a C corporation and contracts must be assigned. A 338(h)(10) election treats a stock deal as an asset sale for tax purposes.", c: ["Stock sale transfers all liabilities and keeps tax basis", "Asset sale allows selecting assets and a basis step-up", "Sellers often face double tax in an asset sale", "338(h)(10) gives step-up in a stock deal"], k: ["Step-up value has to be weighed against extra seller tax cost", "Legal and contract assignment complexity matters in asset deals"], m: ["Thinking a buyer always gets a step-up when buying shares"] },
  { t: "Fixed versus floating exchange ratio", p: "In a stock-for-stock merger, how does a fixed exchange ratio differ from a fixed value structure, and who bears the market risk?", d: 3, tp: "ib-ma", i: "With a fixed exchange ratio the target holders receive a set number of acquirer shares per target share, so the headline deal value moves with the acquirer's share price and target holders bear the price risk, while ownership percentages stay fixed. With a floating ratio the value per target share is fixed and the number of shares adjusts, so acquirer holders bear the dilution risk if their stock falls. Collars set bands within which one structure applies and outside which the other applies, limiting risk to both sides between signing and closing.", c: ["Fixed ratio fixes share count and ownership split", "Floating ratio fixes value per target share", "Risk allocation differs between the two sides", "Collars limit exposure between signing and closing"], k: ["Longer closing periods raise the importance of price protection", "Acquirer's price drop under a floating ratio causes extra shares to be issued"], m: ["Assuming a fixed ratio protects the target's headline value"] },
  { t: "Hostile bids and takeover defenses", p: "How does a hostile takeover work, and what defenses can a target board use?", d: 2, tp: "ib-ma", i: "In a hostile bid the acquirer goes directly to shareholders, via a tender offer, or seeks to replace the board through a proxy fight, after the target board has rejected or ignored a proposal. Defenses include a shareholder rights plan (poison pill) that dilutes a bidder crossing an ownership threshold, a staggered board, supermajority provisions, seeking a white knight or white squire, a leveraged recapitalization, pursuing a competing acquisition and persuading shareholders the offer undervalues the company. Boards must act within fiduciary duties and legal standards of their jurisdiction.", c: ["Tender offer or proxy fight bypasses management", "Poison pill dilutes a bidder passing a threshold", "Staggered board and supermajority provisions slow control change", "White knight or other alternatives and fiduciary constraints"], k: ["Defenses mainly buy time and bargaining power", "A rejected bid can still produce a higher final price"], m: ["Assuming a poison pill makes a takeover impossible"] },
  { t: "Role of a fairness opinion", p: "What is a fairness opinion, who needs one, and what does it actually say?", d: 1, tp: "ib-ma", tp2: "ib-valuation", i: "A fairness opinion is a letter from a financial adviser stating that, as of a date and subject to assumptions and limitations, the consideration in a transaction is fair from a financial point of view to a particular group, usually the target's shareholders. It is supported by valuation work such as DCF, trading comparables and precedent transactions. Boards request one to support their process and reduce litigation risk. It does not say the price is the best available, or recommend how to vote, and it is not a guarantee of value.", c: ["Letter on fairness from a financial point of view", "Supported by DCF, comparables and precedent analysis", "Helps the board show a diligent process", "Does not say the price is the best possible"], k: ["Opinion is given at a point in time based on stated assumptions", "Conflicts such as success-fee arrangements are disclosed"], m: ["Reading it as a recommendation to accept the deal"] },
  { t: "Cost synergies versus revenue synergies", p: "Compare cost and revenue synergies and explain which a banker should treat more cautiously.", d: 1, tp: "ib-ma", i: "Cost synergies come from eliminating duplicated overhead, consolidating facilities, procurement savings and better scale, and are more predictable because the acquirer controls them. Revenue synergies come from cross-selling, wider distribution and pricing power, and they depend on customer reaction and competitors, so they are less certain and slower. Bankers typically include cost synergies in base accretion analysis, show revenue synergies as upside or heavily haircut them, and always include one-time costs to achieve the synergies and a realistic phase-in schedule.", c: ["Cost synergies are controllable and more predictable", "Revenue synergies are uncertain and slow", "Include integration costs and phase-in", "Treat revenue synergies as upside or haircut them"], k: ["Overstated synergies are a common source of failed deals", "Synergy value should be shared, not entirely paid to the target"], m: ["Showing full run-rate synergies in year one"] },
  { t: "Walking through a merger model", p: "Walk through the main steps of building a basic merger model from the assumptions to the EPS impact.", d: 3, tp: "ib-ma", i: "Start with transaction assumptions: offer price, premium, consideration mix, financing terms and fees. Compute equity purchase price, refinanced debt and sources and uses. Build the purchase price allocation to find goodwill and the write-ups. Create the pro forma income statement by combining both companies, adding synergies, subtracting new interest expense, lost interest income and added amortization, and tax-effecting adjustments. Divide pro forma net income by acquirer shares plus new shares to get pro forma EPS and compare with standalone EPS. A full model also adjusts the balance sheet and cash flows for debt paydown.", c: ["Transaction assumptions and sources and uses", "Purchase price allocation and goodwill", "Pro forma income statement with synergies and financing adjustments", "Pro forma EPS versus standalone EPS, with balance sheet effects"], k: ["Adjustments must be tax-effected", "The model should flex the premium, mix and synergies"], m: ["Forgetting new shares or lost interest on cash"] },
  { t: "Relative contribution and ownership in a merger of equals", p: "In a merger of equals, how would you use a contribution analysis to judge what ownership split is fair?", d: 3, tp: "ib-ma", tp2: "ib-valuation", i: "A contribution analysis compares each company's share of combined metrics such as revenue, EBITDA, EBIT, net income and sometimes market capitalization or enterprise value, then converts to implied equity ownership. For metrics measured at the enterprise level, you adjust for each company's net debt to get from implied enterprise contribution to implied equity ownership. The range of implied ownership is compared with the proposed split and the premium each side receives. It ignores differences in growth, margins and risk, so it complements, not replaces, valuation analysis.", c: ["Compare each side's share of revenue, EBITDA and earnings", "Adjust enterprise-level metrics for net debt", "Convert to implied equity ownership", "Limited because growth, margin and risk differ"], k: ["Leverage differences change equity ownership even with equal EBITDA", "Used alongside DCF and market multiples"], m: ["Splitting ownership by EBITDA share without adjusting for debt"] },
  { t: "Auction versus negotiated sale", p: "What are the advantages and disadvantages of a broad auction versus a targeted negotiation when selling a company?", d: 2, tp: "ib-ma", i: "A broad auction creates competition among many bidders, which tends to raise price and terms and gives the board a defensible market check, but it risks leaks, employee and customer disruption and revealing sensitive data to competitors. A targeted process contacts a few likely buyers and preserves confidentiality and speed, but may leave value on the table. Sellers often run a controlled auction in stages: teaser and NDA, confidential information memorandum, first-round indications, management presentations, a data room and final bids, then negotiating the purchase agreement with the best bidder.", c: ["Auction increases competition and price tension", "Confidentiality and disruption risk in a broad process", "Targeted process is faster but may undersell", "Staged process from NDA and CIM to final bids"], k: ["Buyer universe and sensitivity of information drive the choice", "A credible alternative gives sellers leverage"], m: ["Assuming a wider auction always produces the highest value"] },

  { t: "Walking through a basic LBO", p: "Walk me through how a simple leveraged buyout model works from entry to exit.", d: 1, tp: "ib-lbo", i: "A financial sponsor buys a company using a small amount of its own equity and a large amount of debt. Set the purchase price from an entry multiple, build sources and uses including fees, and put the capital structure in place. Project cash flows, and use free cash flow after interest and taxes to repay debt. At exit, usually in three to seven years, apply an exit multiple to final-year EBITDA to get enterprise value, subtract net debt to get equity value, and compare with the equity invested to compute MOIC and IRR.", c: ["Entry price, sources and uses and capital structure", "Projected free cash flow used to repay debt", "Exit value from exit multiple times EBITDA less net debt", "Sponsor returns shown as MOIC and IRR"], k: ["Leverage and debt paydown amplify equity returns", "Assumptions on growth, margin and multiples drive the output"], m: ["Forgetting fees and minimum cash in the uses"] },
  { t: "Three sources of LBO returns", p: "What are the main drivers of returns in an LBO and which is least reliable?", d: 2, tp: "ib-lbo", i: "Returns come from EBITDA growth, from debt paydown and cash generation that raises equity value, and from multiple expansion. EBITDA growth comes from revenue growth and margin improvement. Debt paydown transfers enterprise value from lenders to equity holders as net debt falls. Multiple expansion means selling at a higher multiple than entry. Multiple expansion is the least reliable because it depends on market conditions, so careful sponsors underwrite deals with flat or lower exit multiples and rely on operational improvement and deleveraging.", c: ["EBITDA growth from revenue and margins", "Debt paydown increases equity value", "Multiple expansion", "Multiple expansion is least reliable and often assumed flat"], k: ["Leverage magnifies all three sources", "Value creation attribution helps judge the quality of a deal"], m: ["Relying on multiple expansion to hit the return target"] },
  { t: "What makes a good LBO candidate", p: "List the characteristics that make a company attractive for a leveraged buyout and explain why each matters.", d: 1, tp: "ib-lbo", i: "Strong, stable and predictable free cash flow supports debt service. Low existing leverage leaves debt capacity. Defensible market position, recurring revenue and low cyclicality reduce downside risk. Low capital expenditure and working capital needs mean more cash goes to repay debt. Clear opportunities to cut costs or grow, a capable management team, hard assets for collateral and a reasonable entry valuation with a visible exit route, such as a sale or IPO, also help. Cyclical or capital-intensive firms with volatile cash flows are risky candidates.", c: ["Stable, predictable free cash flow", "Low existing debt and spare capacity", "Low capex needs and defensible market position", "Operational upside and a clear exit path"], k: ["Debt service ability is the central test", "Entry price still determines the return"], m: ["Assuming any profitable company is a good LBO candidate"] },
  { t: "Ability-to-pay analysis", p: "What is an ability-to-pay analysis in an LBO context and what does it tell you?", d: 2, tp: "ib-lbo", tp2: "ib-valuation", i: "An ability-to-pay analysis works backward from a sponsor's required return to the maximum price it could pay. You assume financing at market leverage and rates, set projections and an exit multiple, fix a target IRR such as 20 to 25 percent, and solve for the entry equity cheque and therefore the purchase price that delivers that return. It indicates how much a financial buyer could bid and is used to benchmark against strategic buyers and to set a floor in valuation. Sensitivity tables vary leverage, exit multiple and target IRR.", c: ["Work backward from a target IRR", "Assumes projections, leverage and exit multiple", "Solves for the maximum entry price", "Used as a valuation benchmark with sensitivity tables"], k: ["Sponsors are price-constrained by their return thresholds", "A floor on valuation because strategics often pay more through synergies"], m: ["Treating it as the price a sponsor will actually bid"] },
  { t: "IRR versus MOIC", p: "Explain MOIC and IRR, why a sponsor tracks both, and a case where they tell different stories.", d: 1, tp: "ib-lbo", i: "MOIC, multiple on invested capital, is total proceeds divided by equity invested and ignores time. IRR is the annualized discount rate that sets the present value of the cash flows to zero and accounts for timing. Sponsors track both because a high IRR over a short hold may deliver a small absolute gain, while a high MOIC over a long hold may produce a weak annual return. A dividend recap early in the hold raises IRR by returning cash sooner without changing proceeds much, while a delayed exit lowers IRR even if MOIC is unchanged.", c: ["MOIC is proceeds over equity invested", "IRR accounts for timing of cash flows", "Both are used because each hides something", "Example such as a short hold or early dividend"], k: ["IRR falls the longer you hold for the same multiple", "Funds also have absolute dollar return goals"], m: ["Thinking IRR and MOIC always rank deals identically"] },
  { t: "Mental IRR from a money multiple", p: "Without a calculator, roughly what IRR does a sponsor earn on a 2.0x return in three years and a 2.5x return in five years?", d: 2, tp: "ib-lbo", i: "IRR for a single investment and exit is the multiple raised to one over the years, minus one. A 2.0x multiple over three years is about 2 to the power one-third, about 1.26, so roughly 26 percent. A 2.5x over five years is about 2.5 to the power 0.2, about 1.20, so roughly 20 percent. A common rule of thumb is that 2x in three years is about 26 percent, 2x in five years about 15 percent and 3x in five years about 25 percent. This works when there are no interim cash flows.", c: ["IRR = MOIC to the power 1/years minus 1", "2.0x in three years is about 26 percent", "2.5x in five years is about 20 percent", "Valid only without interim distributions"], k: ["Holding period matters as much as the multiple", "Interim dividends change the calculation"], m: ["Dividing the gain by years to get a simple average"] },
  { t: "Debt tranches in an LBO structure", p: "Describe the typical layers of debt in an LBO from senior to junior and how risk and pricing change along the stack.", d: 2, tp: "ib-lbo", i: "Senior secured bank debt, such as a revolver and term loans, ranks first with collateral and lower interest, often floating-rate, with mandatory amortization and a cash sweep. Next may be second-lien loans, then senior unsecured notes or high-yield bonds with fixed coupons and bullet maturities, and then subordinated or mezzanine debt, which may include PIK interest or warrants. Preferred equity can sit below that. Lower priority means more risk, so higher yield and looser covenants. Revolvers fund working capital needs and are typically undrawn at closing.", c: ["Revolver and senior secured term loans first", "Second lien, senior notes and mezzanine below", "Higher yield for lower priority", "Differences in amortization, covenants and collateral"], k: ["Seniority determines recovery in default", "Cheaper senior debt is limited by lender leverage caps"], m: ["Assuming all debt is repaid at the same pace"] },
  { t: "Cash sweep and mandatory amortization", p: "How do mandatory amortization and a cash sweep work in an LBO model and what is the circularity problem?", d: 3, tp: "ib-lbo", i: "Mandatory amortization is the required scheduled principal repayment on term loans, often a small percentage per year. A cash sweep applies excess free cash flow, after required payments and minimum cash, to prepay prepayable debt, usually starting with the most senior. If interest is calculated on average debt balances, interest depends on repayment, which depends on cash flow after interest, producing a circular reference. Models solve it with iterative calculation and a toggle, or avoid it by computing interest on beginning balances.", c: ["Mandatory amortization is scheduled repayment", "Cash sweep uses excess cash to prepay debt", "Average-balance interest creates circularity", "Iteration with a circuit breaker or beginning balances"], k: ["Sweeps accelerate deleveraging and reduce interest", "Bonds often cannot be prepaid without penalty"], m: ["Sweeping all cash and ignoring minimum cash"] },
  { t: "Effect of a lower exit multiple", p: "A sponsor buys at 10x EBITDA with 5x leverage and sells at 8x EBITDA after five years. Does it necessarily lose money?", d: 3, tp: "ib-lbo", i: "Not necessarily. Equity value at exit equals exit multiple times EBITDA minus net debt. If EBITDA grows substantially and debt is paid down, equity can still increase. For example, with starting EBITDA of 100, entry EV is 1,000, debt 500 and equity 500. If EBITDA reaches 150 and debt falls to 250, exit EV at 8x is 1,200, equity is 950 and MOIC is 1.9x, or about 14 percent IRR. Multiple contraction reduces returns but growth and deleveraging can offset it, and without them leverage magnifies the loss.", c: ["Equity equals exit EV less net debt", "Growth and debt paydown can offset contraction", "Worked example with entry and exit figures", "Leverage amplifies downside if growth fails"], k: ["Sponsors stress test with lower exit multiples", "Return attribution splits EBITDA growth, deleveraging and multiple change"], m: ["Believing contraction always means a loss on a leveraged deal"] },
  { t: "Dividend recapitalization", p: "What is a dividend recap, why do sponsors do them, and what are the risks?", d: 3, tp: "ib-lbo", i: "In a dividend recapitalization the portfolio company raises new debt, often by refinancing or adding a tranche, and pays the proceeds to its owners as a dividend. It returns cash to the sponsor early, which raises IRR because cash arrives sooner, and lets the sponsor de-risk its investment. The risks are higher leverage and interest burden, reduced flexibility in a downturn, covenant pressure and, in the extreme, default, which can harm the company and the sponsor's reputation. Lenders and credit markets must be willing to provide the debt, so recaps are more common when markets are open.", c: ["Company borrows to pay a dividend to the sponsor", "Raises IRR through earlier cash return", "Increases leverage and default risk", "Depends on credit market availability"], k: ["It improves IRR more than MOIC", "Equity cushion falls as leverage rises"], m: ["Thinking a recap creates operating value"] },
  { t: "PIK interest and its effect on deleveraging", p: "What is PIK interest and how does it change a company's debt balance and an LBO model?", d: 3, tp: "ib-lbo", tp2: "ib-accounting", i: "Payment-in-kind interest is interest paid by increasing the principal balance of the debt rather than paying cash. It reduces cash interest burden and improves near-term free cash flow and coverage ratios, but the debt balance compounds, so more must be repaid at maturity. In a model, PIK interest appears as a non-cash interest expense on the income statement that is added back in cash flow and added to the debt balance. It is common in mezzanine and holding-company debt and carries a higher rate than cash-pay debt.", c: ["Interest accrues to principal instead of cash payment", "Improves near-term cash flow", "Debt balance compounds, increasing repayment later", "Non-cash expense added back and added to debt balance"], k: ["It shifts burden to the exit or maturity", "Higher rate compensates lenders for the risk"], m: ["Treating PIK interest as free because no cash leaves the company"] },
  { t: "Why leverage raises returns and risk", p: "Using a simple example, show how leverage increases an investor's return on equity and where it hurts.", d: 1, tp: "ib-lbo", i: "Suppose a business is bought for 100 and sold for 130 after a few years. With all equity, the gain is 30 percent. If 60 is financed with debt at a cost that is low relative to asset growth, equity is 40 and exit equity is 130 minus 60, or 70, so the gain is 75 percent before interest. Leverage works because debt costs less than the return on assets. If the asset falls to 80, unlevered loss is 20 percent but levered equity is 20 against 40, a 50 percent loss, so leverage also magnifies losses and adds default risk.", c: ["Equity return rises when asset return exceeds cost of debt", "Numerical example comparing levered and unlevered returns", "Losses are magnified as well", "Interest and default risk constrain leverage"], k: ["Debt is cheaper because of seniority and tax deductibility", "Equity is the residual claim"], m: ["Ignoring interest cost in the example"] },
  { t: "Sources and uses of funds", p: "What goes into the sources and uses table of an LBO and why must the two sides balance?", d: 1, tp: "ib-lbo", i: "Uses include purchase of the target's equity, refinancing of existing debt, transaction and financing fees, and any cash added to the balance sheet. Sources include new debt tranches, sponsor equity, rollover equity from management, and existing cash on the balance sheet. They must balance because every dollar spent must be funded. Typically the sponsor equity is the plug, calculated as total uses less debt and other sources, which is how the required equity cheque is determined.", c: ["Uses are equity purchase, debt refinancing and fees", "Sources are debt, sponsor equity, rollover and cash", "Sources equal uses", "Sponsor equity commonly the plug"], k: ["Financing fees are capitalized and amortized", "Leverage limits determine how much equity is needed"], m: ["Leaving out fees and refinanced debt"] },
  { t: "Maintenance versus incurrence covenants", p: "What do financial covenants do in leveraged loans and what is the difference between maintenance and incurrence tests?", d: 3, tp: "ib-lbo", i: "Covenants are contractual protections that limit borrower behavior and give lenders early warning. Maintenance covenants, such as maximum leverage or minimum interest coverage, are tested regularly, usually quarterly, and a breach can trigger default whatever the borrower is doing. Incurrence covenants apply only when the borrower takes a specific action such as issuing new debt, paying dividends or making acquisitions, and test whether the ratio would be met after the action. Bank term loans traditionally had maintenance covenants, whereas high-yield bonds and covenant-lite loans rely on incurrence tests, giving borrowers more flexibility.", c: ["Covenants protect lenders and signal distress early", "Maintenance covenants are tested on a schedule", "Incurrence covenants are tested on an action", "Covenant-lite structures favor borrowers"], k: ["Breach gives lenders leverage to renegotiate", "Headroom is built into the LBO case"], m: ["Thinking incurrence covenants can trigger default without any action"] },
  { t: "Sponsor versus strategic buyer valuation", p: "Why can a strategic buyer often pay more for a company than a financial sponsor, and when might the sponsor win anyway?", d: 2, tp: "ib-lbo", tp2: "ib-ma", i: "A strategic buyer can value synergies, such as cost savings and cross-selling, and often has lower required returns than a sponsor targeting 20 percent or more IRR, so it can usually support a higher price. A sponsor is limited by return thresholds and debt capacity, and has no synergies except operational improvements. A sponsor may win when strategics are regulated or constrained, when it offers certainty or speed, when it keeps management involved, when a business is a carve-out, or when credit markets are cheap and aggressive leverage is available.", c: ["Strategics value synergies and accept lower returns", "Sponsors are bound by IRR targets and leverage", "Sponsors may win on speed, certainty or cheap credit", "Antitrust and fit constraints affect strategics"], k: ["Ability-to-pay analysis frames the sponsor's ceiling", "Process dynamics influence who wins"], m: ["Believing sponsors always pay less"] },

  { t: "Stages of an IPO", p: "Describe the main stages of an initial public offering from the decision to go public through the first day of trading.", d: 1, tp: "ib-markets", i: "The company selects bookrunning banks, performs due diligence and prepares the registration statement, including audited financials, risk factors and business description, filed confidentially or publicly with the regulator. Banks and management draft the prospectus, set an initial price range and run a roadshow to gauge investor demand. Bankers build the order book, set the final price and allocate shares, the company is listed and trading begins. Banks often have an over-allotment option, the greenshoe, up to 15 percent of the shares to stabilize aftermarket trading, and lock-up agreements restrict insider sales for a period.", c: ["Bank selection, diligence and registration filing", "Prospectus, price range and roadshow", "Book building, pricing and allocation", "Greenshoe and lock-up agreements"], k: ["The underwriter takes on pricing and distribution risk", "Investor demand can move the price range"], m: ["Believing the IPO price equals the first-day closing price"] },
  { t: "Book building and IPO underpricing", p: "How does book building set an IPO price, and why are IPOs often priced below where they trade on day one?", d: 2, tp: "ib-markets", i: "In book building, underwriters collect indications of demand from institutional investors at different prices during the roadshow, and use the order book to set the offer price and allocate shares. IPOs are often priced at a discount because investors need compensation for information asymmetry and risk, bankers want a successful deal with an oversubscribed book, and a first-day pop creates goodwill with buyers. The cost is borne by existing shareholders as money left on the table, which issuers weigh against certainty of completion.", c: ["Demand collected from investors across prices", "Order book drives price and allocation", "Underpricing compensates for risk and ensures success", "First-day pop is money left on the table"], k: ["Pricing balances the issuer's proceeds and aftermarket stability", "Greenshoe supports the price if demand weakens"], m: ["Assuming a large pop shows a perfectly priced deal"] },
  { t: "Primary versus secondary and follow-on offerings", p: "Differentiate primary, secondary and follow-on equity offerings and explain what a bought deal is.", d: 2, tp: "ib-markets", i: "In a primary offering the company issues new shares and receives the proceeds, diluting existing holders. In a secondary offering existing shareholders sell their shares and the company gets nothing. A follow-on offering is any further sale of shares after an IPO and can be primary, secondary or both. In a bought deal the underwriter commits to buy the whole block at a fixed price, often overnight, and resells it, taking market risk but giving the issuer speed and certainty. Marketed deals involve a roadshow and a wider process before pricing.", c: ["Primary issues new shares and brings proceeds to the company", "Secondary sells existing shares for holders", "Follow-on is any later offering", "Bought deal means underwriter takes risk at fixed price"], k: ["Follow-ons often price at a discount to the last close", "Primary issuance dilutes EPS and ownership"], m: ["Thinking secondaries raise cash for the company"] },
  { t: "Choosing between debt and equity issuance", p: "A company needs capital for an expansion. How would you advise it on whether to issue debt or equity?", d: 2, tp: "ib-markets", tp2: "ib-valuation", i: "Consider the cost, capacity and flexibility of each. Debt is cheaper after tax thanks to interest deductibility and does not dilute ownership, but requires fixed payments, adds default risk and may carry covenants, so it suits stable cash flows and moderate leverage. Equity has no required payments and strengthens the balance sheet but is costlier, dilutes shareholders and may signal that management thinks the stock is overvalued. Advice depends on current leverage versus target, credit rating, cash flow stability, the share price and market windows, and the use of proceeds.", c: ["Debt cheaper with tax shield and no dilution", "Debt brings fixed obligations and default risk", "Equity is costlier and dilutive but flexible", "Rating, leverage target, share price and market conditions"], k: ["Balance sheet capacity is the first constraint", "Issuing equity can send a negative signal"], m: ["Choosing debt only because its coupon is lower than the cost of equity"] },
  { t: "Bond price and yield relationship", p: "Why do bond prices fall when interest rates rise, and what is the relationship between coupon, yield and price?", d: 1, tp: "ib-markets", i: "A bond pays fixed coupons and principal at maturity. If market yields rise, new bonds offer higher coupons, so an existing bond with a lower coupon must trade at a lower price to give buyers the market yield. The price is the present value of the cash flows discounted at the yield, so higher yields lower the present value. A bond trades at a discount when its coupon is below the yield, at par when equal and at a premium when above. Longer maturities and lower coupons make prices more sensitive.", c: ["Price is the present value of coupons and principal", "Price and yield move inversely", "Discount, par and premium depend on coupon versus yield", "Longer maturity means more sensitivity"], k: ["Fixed coupons make old bonds less attractive when rates rise", "Yield to maturity is the discount rate that equates price and cash flows"], m: ["Thinking higher rates lift existing bond prices"] },
  { t: "Duration as rate sensitivity", p: "Explain duration intuitively and how it is used to estimate the price change of a bond for a given change in yield.", d: 2, tp: "ib-markets", i: "Duration measures a bond's price sensitivity to changes in yield and can be viewed as the weighted average time to receive cash flows. Modified duration approximates the percentage price change for a one percentage point yield change: price change is roughly minus modified duration times the yield change. A bond with modified duration of 7 loses about 7 percent if yields rise one point. Duration is higher for longer maturities and lower coupons. The estimate is linear, so convexity corrects for the curvature, especially for large moves.", c: ["Weighted average time to cash flows and measure of sensitivity", "Price change approximately minus modified duration times yield change", "Longer maturity and lower coupon increase duration", "Convexity adjusts for large moves"], k: ["Duration is why long bonds are riskier when rates rise", "Linear estimates overstate losses and understate gains"], m: ["Equating duration with maturity"] },
  { t: "Yield curve shapes and inversion", p: "What does the yield curve show, and what is commonly inferred when it inverts?", d: 2, tp: "ib-markets", i: "The yield curve plots yields on similar-quality bonds, usually government securities, across maturities. It normally slopes upward because investors want compensation for tying up money and bearing inflation and rate risk. An inverted curve has short-term yields above long-term yields, which often reflects market expectations that central bank policy rates will fall because growth will slow, and it has frequently preceded recessions. It is a signal and not a certainty. Curve shape also affects bank margins, since banks borrow short and lend long, and affects issuance and refinancing decisions.", c: ["Yields across maturities for similar-quality bonds", "Normal curve slopes up for term premium", "Inversion reflects expectations of falling rates and weaker growth", "Impacts bank margins and issuer decisions"], k: ["It encodes expectations about policy rates and inflation", "A signal, not a reliable timing tool"], m: ["Stating that an inverted curve causes a recession"] },
  { t: "Investment grade versus high yield", p: "What is a credit rating, and how do investment-grade and high-yield issuers differ in cost and market access?", d: 1, tp: "ib-markets", i: "A credit rating is an agency's opinion of a borrower's ability and willingness to repay. Investment grade is rated BBB minus or Baa3 and above, and anything below is high yield, also called speculative grade or junk. Investment-grade issuers pay lower spreads, have deeper investor bases such as insurers and pension funds, and enjoy broader market access, including longer tenors. High-yield issuers pay higher spreads, face tighter covenants and are more exposed to market windows closing. Ratings reflect leverage, coverage, business risk and competitive position, and changes can move borrowing costs.", c: ["Rating is an opinion on repayment ability", "BBB minus or Baa3 is the investment-grade cutoff", "High yield pays higher spreads and has less access", "Leverage, coverage and business risk drive ratings"], k: ["A downgrade across the line can force some investors to sell", "Spreads compensate for default and illiquidity"], m: ["Thinking ratings are guarantees"] },
  { t: "Chapter 11 versus Chapter 7 and the priority of claims", p: "Compare Chapter 11 reorganization with Chapter 7 liquidation in the US and explain how claims are ranked.", d: 3, tp: "ib-markets", i: "In Chapter 11 a company continues operating under court protection with an automatic stay on creditor actions and develops a plan of reorganization, often reducing debt or converting debt to equity. In Chapter 7 a trustee sells the assets and distributes proceeds. Under the absolute priority rule, secured creditors are paid from their collateral first, then administrative costs and priority claims, then unsecured creditors, then preferred and common equity, so equity is usually wiped out unless creditors are paid in full. Chapter 11 aims to preserve going-concern value above liquidation value.", c: ["Chapter 11 reorganizes under an automatic stay", "Chapter 7 liquidates assets through a trustee", "Secured then unsecured then equity priority", "Going-concern versus liquidation value"], k: ["Creditors vote on the plan by class", "Debtor-in-possession financing can fund the process"], m: ["Thinking equity holders are paid before unsecured creditors"] },
  { t: "Out-of-court restructuring tools", p: "What options does a distressed company have to restructure its debt without filing for bankruptcy, and what holds these deals up?", d: 3, tp: "ib-markets", i: "Options include amend-and-extend, covenant waivers or resets, exchange offers swapping old bonds for new debt or equity, debt buybacks at a discount, asset sales to repay lenders, and injecting new equity. Out-of-court deals are faster and cheaper and avoid court costs and stigma. The barriers are holdout problems, since each creditor may prefer others to take losses, the need for consent thresholds, and conflicts between creditor classes. Liability management exercises and prepackaged bankruptcies can bind holdouts. Advisers analyze the capital structure, liquidity runway and recovery values to find a feasible deal.", c: ["Amend and extend, waivers and exchange offers", "Asset sales and new equity", "Holdout problem and consent thresholds", "Prepackaged bankruptcy as a fallback to bind holdouts"], k: ["Recovery analysis shows whether creditors prefer the deal", "Liquidity runway sets the time available"], m: ["Assuming a restructuring always requires a court filing"] },
  { t: "How rising rates affect deals and valuations", p: "Explain how a sharp rise in interest rates would affect valuations, LBO activity and M&A volume.", d: 2, tp: "ib-markets", tp2: "ib-valuation", i: "Higher rates raise discount rates, lowering the present value of future cash flows and compressing valuation multiples, especially for long-duration growth companies. LBOs are hurt because debt costs more, interest coverage falls and the amount of leverage supported declines, so sponsors can pay less. Financing for acquisitions becomes more expensive, and all-cash buyers find the opportunity cost of cash higher. Volume often drops, as buyers and sellers disagree on prices, while distressed activity and refinancing needs may increase. Stock deals can still work for high-valued acquirers.", c: ["Higher discount rates lower valuations", "LBO leverage capacity and returns fall", "Financing costs rise, buyers and sellers disagree on price", "Distressed and refinancing activity may increase"], k: ["Long-duration assets are the most sensitive", "Rate level and volatility both matter"], m: ["Assuming only debt-funded deals are affected"] },
  { t: "Pitching a stock idea", p: "You are asked to pitch a stock in an interview. How should you structure a concise, credible answer?", d: 1, tp: "ib-markets", tp2: "ib-valuation", i: "Choose a company you understand well and open with the recommendation: buy or sell, and the time horizon. Give a short description of the business and why it matters, then two or three thesis points, such as growth drivers, margin expansion or a mispriced risk. Support with valuation: multiples versus peers or a DCF and a target price. Explain catalysts that will unlock value and the key risks that could prove you wrong, and be ready to answer questions on numbers. Keep it to about two minutes.", c: ["Clear recommendation and horizon", "Short business description and two or three thesis points", "Valuation support and target price", "Catalysts and key risks"], k: ["Specific numbers show real research", "A fresh idea backed by risk awareness beats a famous name"], m: ["Pitching a well-known stock without a differentiated view"] },
  { t: "Framing a markets update answer", p: "An interviewer asks what is going on in the markets right now. How do you prepare and structure an answer that stays useful whatever the date?", d: 1, tp: "ib-markets", i: "Prepare by reading a financial news source daily and tracking a few anchors: the central bank policy rate and its direction, major equity index levels and trend, ten-year government yield, credit spreads, oil and the dollar if relevant, and a couple of recent large deals. In the answer, state the level and direction of two or three indicators, explain what is driving them, such as inflation data or growth worries, and link to the effect on the bank's business, for example IPO windows or M&A activity. Finish with your view and be honest if you do not know a figure.", c: ["Track rates, equity indices, yields and spreads", "State level, direction and the driver for each", "Link to effect on deal activity and the bank's business", "Give an opinion and avoid inventing figures"], k: ["Fresh details prove genuine interest", "Structure prevents rambling"], m: ["Reciting stale data from memory"] },
  { t: "Equity research versus investment banking", p: "How does the role of an equity research analyst differ from that of an investment banker, and how would you value a company as an analyst?", d: 2, tp: "ib-markets", tp2: "ib-valuation", i: "A research analyst covers a sector, builds models and forecasts earnings, and publishes ratings and price targets that inform institutional investors. The work is about independent judgment on public securities, with strict separation from banking to avoid conflicts. A banker advises companies on transactions and capital raising, with deal-driven, execution-focused workflows. An analyst typically values companies with a DCF and with relative valuation, such as P/E, EV/EBITDA and sector-specific metrics, then compares them with consensus expectations to find mispricing. Success is judged on the accuracy and influence of calls.", c: ["Analyst forecasts, rates and sets price targets", "Banker advises on deals and financing", "Chinese wall separates research and banking", "DCF and multiples compared with consensus"], k: ["Research serves investors, banking serves issuers", "Estimates relative to consensus drive stock moves"], m: ["Thinking research ratings are set by the banking team"] },
  { t: "How a convertible bond is priced and why issuers use it", p: "What is a convertible bond, why do issuers sell them and how do investors think about their value?", d: 3, tp: "ib-markets", tp2: "ib-valuation", i: "A convertible bond is a bond that holders can convert into a fixed number of shares, set by the conversion ratio. Issuers get a lower coupon than on straight debt because investors pay for the embedded equity option, and conversion premiums of 20 to 40 percent above the stock price effectively sell stock at a higher price later. Value is roughly the bond floor, the straight bond value, plus the value of the call option on the stock. Investors get downside protection from the bond floor and upside participation if the stock rises. Dilution and credit risk remain concerns for the issuer.", c: ["Bond convertible into shares at a conversion ratio", "Lower coupon because of the embedded option", "Value is bond floor plus equity option", "Issuer dilution and credit risk considerations"], k: ["Conversion premium sets the effective future issue price", "Convertible arbitrage investors hedge the equity exposure"], m: ["Treating converts as free financing"] },

  { t: "Why investment banking", p: "Why do you want to work in investment banking, and how do you answer without sounding rehearsed?", d: 1, tp: "ib-fit", i: "Give two or three specific reasons rooted in evidence from your own experience: for example, you enjoy applying valuation and financial analysis to real strategic decisions, you want steep learning in a short time, and you value working in small teams with high standards. Back each with an example such as a class project, a stock pitch club or prior internship where you saw those aspects. Acknowledge the demands honestly and say why you accept them, and connect to a longer-term goal. Keep it to about a minute and a half.", c: ["Two or three specific reasons", "Evidence from your own experience", "Acknowledges the hours and demands honestly", "Connects to a longer-term goal"], k: ["Specificity beats generic claims about money or prestige", "Authenticity matters more than polish"], m: ["Citing compensation or prestige as the main reason"] },
  { t: "Walk me through your resume", p: "Interviewers often open with walk me through your resume. How should you structure it?", d: 1, tp: "ib-fit", i: "Use a clear chronological storyline of about two minutes that explains why each step led to the next and ends at banking. Start with your education and what drew you to finance, move to the most relevant experiences and highlight one or two accomplishments with concrete results, then explain how those built skills like modelling, analysis and teamwork. Close with why you are applying to this role at this firm. Do not read the page aloud, skip irrelevant detail and be ready to expand on anything you mention.", c: ["Chronological story with a logical thread", "Highlights relevant experiences and results", "Skills linked to banking", "Ends with why this role and firm"], k: ["Every line on the resume can be probed", "Narrative explains choices, not just facts"], m: ["Reciting the resume line by line"] },
  { t: "Strengths for a banking role", p: "What are your top strengths and how would you prove them to an interviewer?", d: 1, tp: "ib-fit", i: "Choose two or three strengths relevant to banking, such as attention to detail, work ethic, quantitative skill, coachability or clear communication. For each give a concrete example with context, action and result, ideally with a number, such as catching an error in a model that changed a recommendation, or balancing coursework and a leadership role. Tie each strength to how it helps on a deal team. Avoid generic adjectives with no proof and avoid listing more than three.", c: ["Two or three relevant strengths", "Specific example for each with result", "Link to day-to-day banking work", "Avoids unsupported adjectives"], k: ["Examples make claims believable", "Relevance is the selection criterion"], m: ["Listing many traits without evidence"] },
  { t: "Discussing a weakness", p: "How do you answer a question about your biggest weakness in a way that is honest but not damaging?", d: 2, tp: "ib-fit", i: "Pick a real, work-relevant weakness that is not central to the role, explain how it showed up, and focus most of the answer on the concrete steps you took and the improvement that resulted. For instance, being reluctant to delegate or to ask for help early, followed by a habit of setting check-in points. Avoid fake weaknesses like I work too hard, and avoid anything that undermines core banking skills like attention to detail. Show self-awareness and ongoing progress.", c: ["Real and non-critical weakness", "Shows how it appeared in practice", "Concrete steps to improve", "Evidence of progress and self-awareness"], k: ["Interviewers test honesty and coachability", "The remedy matters more than the flaw"], m: ["Disguised strengths that sound evasive"] },
  { t: "Handling conflict in a team", p: "Tell me about a time you disagreed with a teammate. How should you structure the answer?", d: 2, tp: "ib-fit", i: "Use a situation, task, action, result structure. Describe the context briefly and what the disagreement was about, focusing on the work and not personalities. Explain what you did: listened to the other view, gathered facts or data, proposed a way forward and, if needed, escalated respectfully. Show that you valued the team outcome and relationship, and state the result and what you learned. Choose an example where you were reasonable and avoid blaming the other person.", c: ["Brief situation and task", "Actions: listening, data and resolution", "Result for the team and relationship", "Lesson learned"], k: ["Interviewers look for maturity and low ego", "Focus on actions you controlled"], m: ["Choosing a story where you were simply right and others wrong"] },
  { t: "Handling long hours and pressure", p: "Banking involves very long hours and tight deadlines. How do you show that you can cope?", d: 2, tp: "ib-fit", i: "Offer evidence, not just assurance. Describe a time you sustained a heavy workload, such as exam period combined with a job or a project with a hard deadline, and what you did: prioritized tasks, planned the work, communicated early about risks and kept the standard of quality. Mention habits that keep you effective, such as sleep, exercise or routines, and show that you understand the realities from conversations with current analysts. Be honest about the demands while showing motivation to learn.", c: ["Concrete example of sustained pressure", "Prioritization and planning actions", "Communicates early about risks", "Shows informed understanding of the lifestyle"], k: ["Evidence is more convincing than saying you do not mind", "Quality must hold under fatigue"], m: ["Claiming the hours do not matter to you"] },
  { t: "A time you made a mistake", p: "Describe a time you made a significant mistake. How should you frame it for a banking interview?", d: 2, tp: "ib-fit", i: "Choose a real mistake with meaningful but recoverable consequences. State what happened and own it without excuses, explain how you discovered and communicated it quickly, and describe the steps taken to fix it. Then show the systems you built to prevent recurrence, such as checklists, double checks or reviewing outputs against sources. Banking values accuracy and honesty, so emphasize transparency and learning, and avoid examples that suggest carelessness about detail.", c: ["Real mistake with ownership", "Prompt disclosure and correction", "Preventive process afterward", "Learning and accountability"], k: ["Early escalation is highly valued in banking", "Preventive systems demonstrate maturity"], m: ["Hiding behind circumstances or a fake mistake"] },
  { t: "Structuring a deal you followed", p: "Tell me about a recent deal you followed. What elements should the answer cover?", d: 2, tp: "ib-fit", tp2: "ib-ma", i: "Pick a recent transaction in a sector you can discuss well. Cover the parties and a one-line summary, the size and structure including consideration type, the strategic rationale for each side, the valuation multiples and premium if known, the financing, expected synergies, regulatory risks and market reaction. Then give your own view on whether the deal made sense and what you would have done differently. Check all the facts, since interviewers will probe details.", c: ["Parties, size and structure", "Strategic rationale and valuation", "Financing, synergies and risks", "Your own opinion on whether it makes sense"], k: ["A point of view differentiates strong candidates", "Accuracy is vital because follow-up questions are likely"], m: ["Describing the deal without any opinion or numbers"] },
  { t: "Why this bank", p: "Why do you want to work at this particular bank rather than another one?", d: 1, tp: "ib-fit", i: "Give specific reasons from research and conversations: strengths in sectors or products you care about, notable recent deals, the culture and team structure described by employees you met, training and analyst development, and platform fit such as global reach or middle-market focus. Name the people you spoke with and what you learned. Show that your reasons are about the firm and not the brand, and connect them to your own strengths and goals. Avoid reasons that apply to any bank.", c: ["Specific products, sectors or deals", "Culture and people from real conversations", "Training and platform fit", "Link to personal goals"], k: ["Networking detail shows genuine effort", "Generic praise signals little preparation"], m: ["Mentioning only the firm's ranking or prestige"] },
  { t: "Why this group or sector", p: "You are interviewing for a specific coverage group such as healthcare or technology. How do you explain your interest in it?", d: 2, tp: "ib-fit", i: "Explain a genuine connection through experience, coursework or curiosity, then show you understand the sector: its key drivers, how companies make money, typical valuation metrics and current themes such as consolidation or regulation. Mention a couple of recent transactions and what makes the group distinctive at this bank. Stay open to the broader program by explaining that you value the learning from the group while remaining flexible if placed elsewhere.", c: ["Genuine reason for interest", "Understanding of sector drivers and valuation", "Reference to recent deals", "Flexibility and fit with the bank's group"], k: ["Sector knowledge shows initiative", "Too narrow a focus may seem inflexible"], m: ["Claiming interest in a sector without being able to discuss it"] },
  { t: "Leadership example", p: "Give an example of a time you led others. How should you tell it?", d: 2, tp: "ib-fit", i: "Choose an example where you influenced outcomes, even without formal authority, such as running a club, a group project or a student fund. Describe the goal and the challenge, the specific steps you took to organize and motivate people, how you handled differing views and the result with measurable detail. Credit teammates, show how you adapted your approach to individuals and say what you learned about leadership. Analysts rarely manage others, so emphasize initiative and ownership.", c: ["Clear goal and challenge", "Concrete actions to organize and motivate", "Quantified result and credit to the team", "Reflection on lessons learned"], k: ["Leadership means ownership of outcomes, not title", "Humility is credible"], m: ["Describing only your title without actions"] },
  { t: "Attention to detail example", p: "Banking analysts must be accurate. Give an example showing your attention to detail and the process behind it.", d: 2, tp: "ib-fit", i: "Describe a specific project where accuracy mattered, such as a financial model, research report or audit task. Explain the process you used: checking calculations against sources, using consistent formatting, building checks into the model, and reviewing the work after a break or with a colleague. Mention an actual error you caught and its impact. Explain why this habit would matter for slides and models that clients rely on, and avoid vague claims such as I am detail-oriented.", c: ["Specific project where accuracy mattered", "Concrete process and checks", "Example of an error caught and its impact", "Link to banking deliverables"], k: ["Process shows reliability beyond a trait claim", "Small errors can damage credibility with clients"], m: ["Asserting a trait without any example"] },
  { t: "Handling critical feedback", p: "How do you respond when a senior colleague heavily criticizes your work, and what example can you give?", d: 2, tp: "ib-fit", i: "Say that you listen without defensiveness, clarify what is expected, fix the work quickly and apply the lesson to future work. Give a real example, for example a professor or manager who marked up your analysis: describe the feedback, the concrete changes you made, how you checked your next output against the standard and the improvement that followed. Mention seeking feedback proactively. Banking has steep learning curves with frequent markups, so show that you see feedback as the fastest way to improve.", c: ["Listens without defensiveness and clarifies", "Acts on feedback quickly", "Specific example with outcome", "Seeks feedback proactively"], k: ["Coachability is a key selection criterion", "Heavy edits are normal for junior bankers"], m: ["Describing feedback as unfair or taking it personally"] },
  { t: "Explaining a non-finance background", p: "You come from a non-finance major or career. How do you convince interviewers you can succeed in banking?", d: 3, tp: "ib-fit", i: "Address the gap directly and with evidence. Explain why you chose banking, and show you have built the technical foundation: courses, self-study of accounting, valuation and modelling, a certification or a stock pitch, and be ready to demonstrate it. Highlight transferable strengths from your background, such as analytical rigor, communication, or work under deadlines, with examples. Show commitment through networking and informed conversations with bankers. Be ready for technical questions, because they will test whether the gap is real.", c: ["Addresses the gap directly", "Evidence of technical preparation", "Transferable skills with examples", "Demonstrated commitment through networking"], k: ["Proving technical competence removes the main concern", "A distinctive background can be an advantage if linked to banking"], m: ["Apologizing for the background instead of presenting it as an asset"] },
  { t: "Questions to ask the interviewer", p: "At the end of an interview you are asked whether you have questions. What makes a strong set of questions?", d: 1, tp: "ib-fit", i: "Ask two or three thoughtful questions that show research and genuine curiosity, such as what the interviewer found surprising about the first year, how deal staffing works in the group, or how the team handled a recent transaction. Ask about their experience and career since people enjoy sharing it. Avoid questions answered on the website, about pay, hours or benefits, or anything that sounds like a test. Listen to answers and respond naturally, and thank them, since it also helps build the relationship for later follow-up.", c: ["Two or three thoughtful, researched questions", "Asks about the interviewer's own experience", "Avoids questions on pay or easily found facts", "Engages with the answers and follows up"], k: ["Questions leave a lasting impression", "Curiosity is a signal of fit"], m: ["Saying you have no questions"] },
];
